cd /tmp/neutrino-fast-live-LY3jZs/parallel_analysis/fast_dag/0 && node <<'EOF'
const fs = require('fs'), assert = require('assert');
const regions = ['north','south','east','west'];
const recomputed = {};
for (const r of regions) {
  const raw = fs.readFileSync(`${r}.json`, 'utf8');
  const data = JSON.parse(raw);
  assert(Array.isArray(data), `${r}: not an array`);
  data.forEach((rec, i) => {
    for (const k of ['id','units','weight']) assert(Number.isFinite(rec[k]), `${r}[${i}].${k} not numeric`);
  });
  const ids = data.map(d => d.id);
  assert.strictEqual(new Set(ids).size, ids.length, `${r}: duplicate ids`);
  // completeness: ids must be 1..n contiguous
  ids.forEach((id, i) => assert.strictEqual(id, i + 1, `${r}: id gap at index ${i}`));
  const count = data.length;
  const units = data.reduce((a, b) => a + b.units, 0);
  const weighted = data.reduce((a, b) => a + b.units * b.weight, 0);
  // independent second arithmetic: explicit loop, bigint cross-check
  let u2 = 0n, w2 = 0n;
  for (const d of data) { u2 += BigInt(d.units); w2 += BigInt(d.units) * BigInt(d.weight); }
  assert.strictEqual(u2, BigInt(units), `${r}: bigint units mismatch`);
  assert.strictEqual(w2, BigInt(weighted), `${r}: bigint weighted mismatch`);
  recomputed[r] = { count, units, weighted };
}
const gU = regions.reduce((a, r) => a + recomputed[r].units, 0);
const gW = regions.reduce((a, r) => a + recomputed[r].weighted, 0);
console.log('RECOMPUTED', JSON.stringify(recomputed), 'grand', gU, gW);

const ans = JSON.parse(fs.readFileSync('answer.json', 'utf8'));
assert.deepStrictEqual(Object.keys(ans).sort(), ['grand_units','grand_weighted','regions']);
assert.deepStrictEqual(Object.keys(ans.regions).sort(), ['east','north','south','west']);
for (const r of regions) {
  assert.deepStrictEqual(Object.keys(ans.regions[r]).sort(), ['count','units','weighted'], `${r}: wrong keys`);
  assert.deepStrictEqual(ans.regions[r], recomputed[r], `${r}: value mismatch`);
}
assert.strictEqual(ans.grand_units, gU, 'grand_units mismatch');
assert.strictEqual(ans.grand_weighted, gW, 'grand_weighted mismatch');
assert.strictEqual(ans.grand_units, regions.reduce((a,r)=>a+ans.regions[r].units,0));
assert.strictEqual(ans.grand_weighted, regions.reduce((a,r)=>a+ans.regions[r].weighted,0));
console.log('GRAND_OK', ans.grand_units === gU && ans.grand_weighted === gW);
for (const r of regions) console.log(r, 'answer==recompute', JSON.stringify(ans.regions[r]) === JSON.stringify(recomputed[r]));
console.log('ALL_ASSERTS_PASSED');
EOF
